let connection=null,plan=null;const $=s=>document.querySelector(s),status=s=>$('#status').textContent=s;
async function api(path,method='GET',body){if(!connection)throw Error('Connect your deployment first.');const r=await fetch(connection.url+path,{method,headers:{Authorization:'Bearer '+connection.key,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error(r.status===401?'Access key does not match.':'Scheduler unavailable. Check deployment, environment variables, database schema and CORS configuration.');return r.json();}
$('#connect').onclick=async()=>{try{const u=new URL($('#url').value);if(u.protocol!=='https:'||u.pathname!=='/'||u.search||u.hash)throw Error('Enter only an HTTPS deployment origin.');if($('#key').value.length<32)throw Error('Enter your generated ADMIN_TOKEN.');connection={url:u.origin,key:$('#key').value};await refresh();status('Connected. Watch status comes from your private deployment.');}catch(e){connection=null;status(e.message);}};
$('#disconnect').onclick=()=>{connection=null;$('#key').value='';$('#events').replaceChildren();status('Disconnected. Existing scheduled watches continue until paused or expired.');};
$('#file').onchange=async e=>{try{plan=JSON.parse(await e.target.files[0].text());if(plan.version!==1||!plan.doctor||!plan.date)throw Error('Invalid booking plan.');status('Plan loaded in page memory. It has not been sent.');}catch{plan=null;status('Import a valid SlotCare booking plan JSON.');}};
$('#watchForm').onsubmit=async e=>{e.preventDefault();try{if(!plan)throw Error('Import your booking plan first.');const preferences={};for(const k of ['city','department','centre','doctor','date','start','end'])preferences[k]=plan[k];await api('/api/watches','POST',{preferences,runnerId:$('#runner').value,intervalSeconds:Number($('#interval').value),startsAt:$('#startsAt').value?$('#startsAt').value+':00+05:30':null});await refresh();status('Watch created. It will stay queued until your browser worker processes it.');}catch(e){status(e.message);}};
async function refresh(){const {watches}=await api('/api/watches');const box=$('#events');box.replaceChildren();if(!watches.length){box.textContent='No scheduled watches yet.';return;}for(const w of watches){const row=document.createElement('div');row.className='watch-row';const h=document.createElement('strong');h.textContent=w.preferences.doctor;const p=document.createElement('p');p.textContent=`${w.preferences.date} · ${w.preferences.start}–${w.preferences.end} IST · every ${w.interval_seconds/60} min`;const tag=document.createElement('span');tag.className='tag';tag.textContent=w.status==='available'?'Slot seen at '+w.last_result.time+' IST':w.status;const checked=document.createElement('p');checked.className='fine';checked.textContent=w.last_checked?'Last actual check: '+new Date(w.last_checked).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST':'No actual CGHS slot check has run yet.';const b=document.createElement('button');b.className='secondary';b.textContent=w.enabled?'Pause':'Resume';b.onclick=async()=>{try{await api('/api/watches','PATCH',{id:w.id,enabled:!w.enabled});await refresh();}catch(e){status(e.message);}};row.append(h,p,tag,checked,b);box.append(row);}}
$('#refresh').onclick=()=>refresh().catch(e=>status(e.message));
